window.TALK_ENGLISH_WORDS = {"home": {"en": "Home", "id": "Beranda", "th": "หน้าแรก"}, "about": {"en": "About George", "id": "Tentang George", "th": "เกี่ยวกับ George"}, "story": {"en": "Our story", "id": "Cerita kami", "th": "เรื่องราวของเรา"}, "find": {"en": "Find your course", "id": "Temukan kursus Anda", "th": "ค้นหาหลักสูตรที่เหมาะกับคุณ"}, "courses": {"en": "Courses", "id": "Kursus", "th": "หลักสูตร"}, "learners": {"en": "Learner stories", "id": "Cerita siswa", "th": "เรื่องราวผู้เรียน"}, "online": {"en": "Learn online", "id": "Belajar online", "th": "เรียนออนไลน์"}, "faq": {"en": "Questions", "id": "Pertanyaan", "th": "คำถามที่พบบ่อย"}, "login": {"en": "Student Area", "id": "Area Siswa", "th": "พื้นที่ผู้เรียน"}, "contact": {"en": "Contact", "id": "Hubungi kami", "th": "ติดต่อเรา"}, "trial": {"en": "Free trial lesson", "id": "Kelas percobaan gratis", "th": "บทเรียนทดลองฟรี"}, "hero": {"en": "Build confidence. Open new opportunities.", "id": "Bangun percaya diri. Buka peluang baru.", "th": "สร้างความมั่นใจ เปิดโอกาสใหม่"}, "intro": {"en": "Practical spoken English for adults who want more confidence at work and in everyday life.", "id": "Bahasa Inggris praktis untuk orang dewasa yang ingin lebih percaya diri di tempat kerja dan kehidupan sehari-hari.", "th": "ภาษาอังกฤษเพื่อการสื่อสารสำหรับผู้ใหญ่ที่ต้องการความมั่นใจในการทำงานและชีวิตประจำวัน"}, "heroLabel": {"en": "Canadian teaching approach · Practical English", "id": "Pendekatan mengajar Kanada · Bahasa Inggris praktis", "th": "แนวทางการสอนจากแคนาดา · ภาษาอังกฤษใช้งานจริง"}, "trust": {"en": "Real conversations · Patient guidance · Small groups", "id": "Percakapan nyata · Bimbingan sabar · Kelompok kecil", "th": "บทสนทนาจริง · คำแนะนำอย่างใจเย็น · กลุ่มเล็ก"}, "promoTitle": {"en": "Start speaking English with more confidence", "id": "Mulai berbicara bahasa Inggris dengan lebih percaya diri", "th": "เริ่มพูดภาษาอังกฤษอย่างมั่นใจขึ้น"}, "promoText": {"en": "Choose a goal, try the optional course finder, then agree a starting point with Teacher George. No payment or account is needed to ask about a trial.", "id": "Pilih tujuan, coba panduan kursus opsional, lalu tentukan titik awal bersama Teacher George. Tidak perlu membayar atau membuat akun untuk menanyakan kelas percobaan.", "th": "เลือกเป้าหมาย ลองแบบแนะนำหลักสูตรตามความสมัครใจ แล้วพูดคุยกับ Teacher George เพื่อเลือกจุดเริ่มต้น ไม่ต้องชำระเงินหรือสร้างบัญชีเพื่อสอบถามบทเรียนทดลอง"}, "noPressure": {"en": "Free consultation. No obligation to enrol.", "id": "Konsultasi gratis. Tidak wajib mendaftar kursus.", "th": "ปรึกษาฟรี ไม่มีข้อผูกมัดในการสมัครเรียน"}, "noPerfect": {"en": "You do not need to be perfect to begin", "id": "Anda tidak harus sempurna untuk memulai", "th": "ไม่ต้องสมบูรณ์แบบก็เริ่มได้"}, "noPerfectText": {"en": "You can ask questions, make mistakes and practise in a friendly, respectful environment. We build confidence one conversation at a time.", "id": "Anda boleh bertanya, membuat kesalahan, dan berlatih dalam suasana ramah dan saling menghormati. Kepercayaan diri tumbuh dari satu percakapan ke percakapan berikutnya.", "th": "คุณถามคำถาม ทำผิด และฝึกได้ในบรรยากาศที่เป็นมิตรและให้เกียรติ เราสร้างความมั่นใจทีละบทสนทนา"}, "optionalPractice": {"en": "Practice outside class is optional. Homework, recordings and submissions are not compulsory; we practise the essentials together in class.", "id": "Latihan di luar kelas bersifat opsional. Tugas, rekaman, dan pengumpulan jawaban tidak wajib; kita berlatih hal penting bersama di kelas.", "th": "การฝึกนอกชั้นเรียนเป็นทางเลือก ไม่บังคับทำการบ้าน อัดเสียง หรือส่งงาน เราฝึกส่วนสำคัญร่วมกันในชั้นเรียน"}, "founder": {"en": "Meet the founder", "id": "Kenali pendiri kami", "th": "พบกับผู้ก่อตั้ง"}, "founderTitle": {"en": "Hello, I am George", "id": "Halo, saya George", "th": "สวัสดี ผม George"}, "founderText": {"en": "I teach live from Canada. My focus is practical conversation, understandable pronunciation and the confidence to keep speaking. Lessons use simple English with local-language written guidance.", "id": "Saya mengajar langsung dari Kanada. Fokus saya adalah percakapan praktis, pelafalan yang mudah dipahami, dan kepercayaan diri untuk terus berbicara. Kelas menggunakan bahasa Inggris sederhana dengan panduan tertulis berbahasa Indonesia.", "th": "ผมสอนสดจากแคนาดา โดยเน้นบทสนทนาใช้งานจริง การออกเสียงที่เข้าใจได้ และความมั่นใจในการพูดต่อ บทเรียนใช้ภาษาอังกฤษง่าย ๆ พร้อมคำแนะนำภาษาไทยแบบเขียน"}, "founderExperience": {"en": "In 2005-2006, I contributed 93 volunteer hours to the Toronto Catholic District School Board Adult Education Program in Canada.", "id": "Pada 2005-2006, saya menyumbangkan 93 jam sebagai sukarelawan dalam Program Pendidikan Dewasa Toronto Catholic District School Board di Kanada.", "th": "ในปี 2005-2006 ผมทำงานอาสาสมัคร 93 ชั่วโมงในโครงการการศึกษาผู้ใหญ่ของ Toronto Catholic District School Board ในแคนาดา"}, "storyTitle": {"en": "Language can open doors", "id": "Bahasa dapat membuka peluang", "th": "ภาษาเปิดโอกาสได้"}, "storyText": {"en": "Moving to Canada taught me how much everyday communication matters for work, relationships and belonging. Adults deserve practical guidance and patient encouragement.", "id": "Pindah ke Kanada mengajarkan saya pentingnya komunikasi sehari-hari untuk pekerjaan, hubungan, dan rasa memiliki. Orang dewasa layak mendapat bimbingan praktis dan dorongan yang sabar.", "th": "การย้ายมาแคนาดาทำให้ผมเห็นความสำคัญของการสื่อสารต่อการทำงาน ความสัมพันธ์ และความรู้สึกเป็นส่วนหนึ่ง ผู้ใหญ่ควรได้รับคำแนะนำที่ใช้ได้จริงและกำลังใจอย่างใจเย็น"}, "expansion": {"en": "Teaching learners in Vietnam. Now welcoming learners in Thailand and Indonesia.", "id": "Mengajar siswa di Vietnam. Kini menyambut siswa di Thailand dan Indonesia.", "th": "สอนผู้เรียนในเวียดนาม และกำลังต้อนรับผู้เรียนในไทยและอินโดนีเซีย"}, "why": {"en": "Why choose Talk English?", "id": "Mengapa memilih Talk English?", "th": "ทำไมจึงเลือก Talk English"}, "liveTitle": {"en": "Live through Microsoft Teams", "id": "Kelas langsung melalui Microsoft Teams", "th": "เรียนสดผ่าน Microsoft Teams"}, "liveText": {"en": "Join George from your computer, tablet or phone.", "id": "Belajar bersama George melalui komputer, tablet, atau ponsel.", "th": "เรียนกับ George ผ่านคอมพิวเตอร์ แท็บเล็ต หรือโทรศัพท์"}, "realTitle": {"en": "Practise real situations", "id": "Berlatih situasi nyata", "th": "ฝึกสถานการณ์จริง"}, "realText": {"en": "Use useful language for work, travel and everyday conversations.", "id": "Gunakan bahasa yang berguna untuk pekerjaan, perjalanan, dan percakapan sehari-hari.", "th": "ใช้ภาษาในการทำงาน การเดินทาง และบทสนทนาในชีวิตประจำวัน"}, "feedbackTitle": {"en": "Personal feedback", "id": "Umpan balik pribadi", "th": "คำแนะนำเฉพาะบุคคล"}, "feedbackText": {"en": "Get help with pronunciation, useful words and clear replies.", "id": "Dapatkan bantuan pelafalan, kosakata yang berguna, dan jawaban yang jelas.", "th": "รับคำแนะนำเรื่องการออกเสียง คำศัพท์ และการตอบให้ชัดเจน"}, "supportTitle": {"en": "Guidance when you need it", "id": "Panduan saat dibutuhkan", "th": "คำแนะนำเมื่อคุณต้องการ"}, "supportText": {"en": "Ask about registration, course choices, schedules and access.", "id": "Tanyakan pendaftaran, pilihan kursus, jadwal, dan akses.", "th": "สอบถามเรื่องการสมัคร หลักสูตร ตารางเรียน และการเข้าใช้งาน"}, "catalogIntro": {"en": "14 practical adult course categories. Each adult course has 16 lessons in four packages of four, with 50 minutes per lesson.", "id": "14 kategori kursus praktis untuk dewasa. Setiap kursus terdiri dari 16 pelajaran dalam empat paket berisi empat pelajaran, masing-masing 50 menit.", "th": "หลักสูตรใช้งานจริงสำหรับผู้ใหญ่ 14 กลุ่ม แต่ละหลักสูตรมี 16 บทเรียน แบ่งเป็น 4 ชุด ชุดละ 4 บทเรียน บทเรียนละ 50 นาที"}, "materialsNotice": {"en": "Full localized materials remain under review. Course enquiries do not guarantee that every lesson is already available in the Student Area. Availability is confirmed before enrolment.", "id": "Materi lengkap berbahasa Indonesia masih ditinjau. Pertanyaan kursus tidak menjamin semua pelajaran sudah tersedia di Area Siswa. Ketersediaan dikonfirmasi sebelum pendaftaran.", "th": "สื่อภาษาไทยฉบับเต็มยังอยู่ระหว่างตรวจทาน การสอบถามหลักสูตรไม่ได้ยืนยันว่าทุกบทเรียนพร้อมในพื้นที่ผู้เรียน จะยืนยันความพร้อมก่อนสมัคร"}, "adultCourses": {"en": "Adult and specialist courses", "id": "Kursus dewasa dan bidang pekerjaan", "th": "หลักสูตรผู้ใหญ่และภาษาอังกฤษเฉพาะงาน"}, "specialPrograms": {"en": "Separate programmes", "id": "Program terpisah", "th": "โปรแกรมแยกต่างหาก"}, "enquireCourse": {"en": "Ask about this course", "id": "Tanyakan kursus ini", "th": "สอบถามหลักสูตรนี้"}, "practicalNotice": {"en": "Basic, practical English, not an academic qualification or occupational certification. Love Across Borders is for adults aged 18+. Corporate classes are separate from adult 50-minute courses.", "id": "Bahasa Inggris dasar dan praktis, bukan kualifikasi akademik atau sertifikasi profesi. Love Across Borders untuk dewasa 18+. Kelas perusahaan terpisah dari kursus dewasa 50 menit.", "th": "ภาษาอังกฤษพื้นฐานที่ใช้ได้จริง ไม่ใช่วุฒิการศึกษาหรือใบรับรองวิชาชีพ Love Across Borders สำหรับผู้ใหญ่ 18 ปีขึ้นไป ชั้นเรียนองค์กรแยกจากหลักสูตรผู้ใหญ่ครั้งละ 50 นาที"}, "interviewNotice": {"en": "Beginner and Advanced interview pathways; each has 16 lessons. George confirms suitability through conversation.", "id": "Jalur wawancara Beginner dan Advanced; masing-masing 16 pelajaran. George mengonfirmasi kesesuaian melalui percakapan.", "th": "เส้นทางสัมภาษณ์งาน Beginner และ Advanced เส้นทางละ 16 บทเรียน George จะยืนยันความเหมาะสมผ่านการสนทนา"}, "kidsNotice": {"en": "Age groups 4-6, 7-9 and 10-12. A parent or guardian completes the enquiry. Activities, suitability and guardian arrangements are confirmed before enrolment.", "id": "Kelompok usia 4-6, 7-9, dan 10-12. Orang tua atau wali mengisi pertanyaan. Kegiatan, kesesuaian, dan pengaturan pendampingan dikonfirmasi sebelum pendaftaran.", "th": "กลุ่มอายุ 4-6, 7-9 และ 10-12 ปี ผู้ปกครองเป็นผู้กรอกข้อมูล จะยืนยันกิจกรรม ความเหมาะสม และการดูแลก่อนสมัคร"}, "pricing": {"en": "Choose a practical starting package", "id": "Pilih paket awal yang praktis", "th": "เลือกชุดเรียนเริ่มต้นที่เหมาะกับคุณ"}, "pricingIntro": {"en": "Start with a free trial, then choose the payment option that suits you. Group prices are per learner, with up to six learners.", "id": "Mulai dengan kelas percobaan gratis, lalu pilih cara pembayaran yang sesuai. Harga kelompok per siswa, maksimal enam siswa.", "th": "เริ่มด้วยบทเรียนทดลองฟรี แล้วเลือกวิธีชำระที่เหมาะกับคุณ ราคากลุ่มคิดต่อผู้เรียน กลุ่มละไม่เกิน 6 คน"}, "trialDetail": {"en": "60 minutes to discuss your goals, practise a short conversation and agree a suitable starting point.", "id": "60 menit untuk membahas tujuan, mencoba percakapan singkat, dan menentukan titik awal yang sesuai.", "th": "60 นาทีเพื่อพูดคุยเป้าหมาย ลองสนทนาสั้น ๆ และเลือกจุดเริ่มต้นที่เหมาะสม"}, "free": {"en": "Free", "id": "Gratis", "th": "ฟรี"}, "single": {"en": "One group class", "id": "Satu kelas kelompok", "th": "ชั้นเรียนกลุ่ม 1 ครั้ง"}, "singleDetail": {"en": "50 minutes. Pay for one confirmed class at a time.", "id": "50 menit. Bayar satu kelas yang telah dikonfirmasi setiap kali.", "th": "50 นาที ชำระครั้งละ 1 ชั้นเรียนที่ยืนยันแล้ว"}, "bundle": {"en": "Four-class group package", "id": "Paket empat kelas kelompok", "th": "ชุดเรียนกลุ่ม 4 ครั้ง"}, "bundleDetail": {"en": "4 x 50 minutes. Save 12.5% compared with four individual group classes.", "id": "4 x 50 menit. Hemat 12,5% dibandingkan empat kelas kelompok yang dibayar satu per satu.", "th": "4 ครั้ง ครั้งละ 50 นาที ประหยัด 12.5% เมื่อเทียบกับชำระชั้นเรียนกลุ่มแยก 4 ครั้ง"}, "otherPrices": {"en": "Private lessons, interview workshops, corporate groups and Kids: fees confirmed in writing after discussing your needs.", "id": "Kelas privat, lokakarya wawancara, kelompok perusahaan, dan Kids: biaya dikonfirmasi tertulis setelah membahas kebutuhan Anda.", "th": "บทเรียนส่วนตัว เวิร์กช็อปสัมภาษณ์ กลุ่มองค์กร และ Kids จะยืนยันค่าเรียนเป็นลายลักษณ์อักษรหลังพูดคุยความต้องการ"}, "paymentPolicy": {"en": "No online checkout. Fees, availability, package dates, rescheduling and refund terms are confirmed in writing before payment. An enquiry does not reserve a place or confirm a paid enrolment.", "id": "Tidak ada pembayaran online di situs. Biaya, ketersediaan, tanggal paket, penjadwalan ulang, dan ketentuan pengembalian dana dikonfirmasi tertulis sebelum pembayaran. Pertanyaan tidak memesan tempat atau mengonfirmasi pendaftaran berbayar.", "th": "เว็บไซต์ยังไม่มีระบบชำระเงิน จะยืนยันค่าเรียน ที่ว่าง วันที่เรียน การเปลี่ยนเวลา และเงื่อนไขคืนเงินเป็นลายลักษณ์อักษรก่อนชำระ การสอบถามไม่ได้จองที่หรือยืนยันการสมัครแบบชำระเงิน"}, "referral": {"en": "Learning is better together", "id": "Belajar lebih menyenangkan bersama", "th": "เรียนรู้ร่วมกันได้ดียิ่งขึ้น"}, "referralText": {"en": "Friends can ask about joining the same small group. The four-class package saving applies per learner; no extra referral reward is promised.", "id": "Teman dapat menanyakan bergabung dalam kelompok kecil yang sama. Penghematan paket empat kelas berlaku per siswa; tidak ada hadiah referensi tambahan yang dijanjikan.", "th": "เพื่อนสามารถสอบถามการเข้ากลุ่มเล็กเดียวกัน ส่วนลดชุดเรียน 4 ครั้งคิดต่อผู้เรียน โดยไม่มีคำสัญญาว่าจะมีรางวัลแนะนำเพื่อนเพิ่ม"}, "schedule": {"en": "Class times in your local time zone", "id": "Jadwal kelas menurut zona waktu Anda", "th": "เวลาเรียนตามเขตเวลาของคุณ"}, "morning": {"en": "Morning options", "id": "Pilihan pagi", "th": "ช่วงเช้า"}, "evening": {"en": "Evening options", "id": "Pilihan sore dan malam", "th": "ช่วงเย็น"}, "scheduleText": {"en": "Tell us your preferred days and time window. George confirms the exact date, time and availability before booking. Canadian daylight saving can change the time difference by one hour.", "id": "Beri tahu hari dan rentang waktu pilihan Anda. George mengonfirmasi tanggal, jam, dan ketersediaan sebelum pemesanan. Perubahan waktu musim di Kanada dapat mengubah selisih satu jam.", "th": "แจ้งวันและช่วงเวลาที่สะดวก George จะยืนยันวันที่ เวลา และที่ว่างก่อนจอง เวลาออมแสงในแคนาดาอาจทำให้เวลาต่างกันเปลี่ยน 1 ชั่วโมง"}, "onlineIntro": {"en": "Live teaching, wherever you learn", "id": "Kelas langsung, di mana pun Anda belajar", "th": "เรียนสดได้จากที่ที่คุณสะดวก"}, "step1": {"en": "Tell us your goal", "id": "Ceritakan tujuan Anda", "th": "บอกเป้าหมายของคุณ"}, "step2": {"en": "Agree a time and receive your Teams link", "id": "Sepakati jadwal dan terima tautan Teams", "th": "ตกลงเวลาและรับลิงก์ Teams"}, "step3": {"en": "Start speaking with support", "id": "Mulai berbicara dengan bimbingan", "th": "เริ่มพูดพร้อมคำแนะนำ"}, "team": {"en": "Your teaching and support", "id": "Pengajaran dan dukungan untuk Anda", "th": "การสอนและการดูแลของคุณ"}, "georgeRole": {"en": "Founder and English communication teacher", "id": "Pendiri dan pengajar komunikasi bahasa Inggris", "th": "ผู้ก่อตั้งและครูสอนการสื่อสารภาษาอังกฤษ"}, "virtual": {"en": "Virtual advisor", "id": "Penasihat virtual", "th": "ที่ปรึกษาเสมือน"}, "advisorText": {"en": "Guidance on course choices, registration, schedules and Student Area access. Choose a help topic or send an enquiry.", "id": "Panduan pilihan kursus, pendaftaran, jadwal, dan akses Area Siswa. Pilih topik bantuan atau kirim pertanyaan.", "th": "คำแนะนำเรื่องหลักสูตร การสมัคร ตารางเรียน และการเข้าพื้นที่ผู้เรียน เลือกหัวข้อช่วยเหลือหรือส่งคำถาม"}, "advisorDisclosure": {"en": "Virtual character with prepared guidance. Personal enquiries are handled by the Talk English team.", "id": "Karakter virtual dengan panduan yang telah disiapkan. Pertanyaan pribadi ditangani oleh tim Talk English.", "th": "ตัวละครเสมือนพร้อมคำแนะนำที่เตรียมไว้ ทีม Talk English ดูแลคำถามส่วนตัว"}, "contactAdvisor": {"en": "Contact your advisor", "id": "Hubungi penasihat Anda", "th": "ติดต่อที่ปรึกษาของคุณ"}, "help": {"en": "Student help", "id": "Bantuan siswa", "th": "ความช่วยเหลือผู้เรียน"}, "emailAdvisor": {"en": "Email your advisor", "id": "Email penasihat Anda", "th": "ส่งอีเมลถึงที่ปรึกษา"}, "whatsapp": {"en": "Message on WhatsApp", "id": "Kirim pesan WhatsApp", "th": "ส่งข้อความทาง WhatsApp"}, "vietnamStories": {"en": "Experiences from our learners in Vietnam", "id": "Pengalaman siswa kami di Vietnam", "th": "ประสบการณ์จากผู้เรียนของเราในเวียดนาม"}, "storiesIntro": {"en": "These experiences come from our Vietnam classes, not from learners in Thailand or Indonesia. Individual experiences vary.", "id": "Pengalaman ini berasal dari kelas kami di Vietnam, bukan dari siswa di Thailand atau Indonesia. Pengalaman setiap orang berbeda.", "th": "เรื่องราวเหล่านี้มาจากชั้นเรียนในเวียดนาม ไม่ใช่ผู้เรียนในไทยหรืออินโดนีเซีย ประสบการณ์ของแต่ละคนแตกต่างกัน"}, "storyAn": {"en": "I used to be afraid of pronouncing words incorrectly. Now I can understand and use many more common expressions.", "id": "Dulu saya takut salah melafalkan kata. Sekarang saya dapat memahami dan menggunakan lebih banyak ungkapan umum.", "th": "เมื่อก่อนฉันกลัวออกเสียงผิด ตอนนี้ฉันเข้าใจและใช้สำนวนทั่วไปได้มากขึ้น"}, "storyChung": {"en": "I discovered that I can improve when I practise regularly and remain persistent.", "id": "Saya menyadari bahwa saya bisa berkembang jika berlatih teratur dan tetap tekun.", "th": "ฉันพบว่าตัวเองพัฒนาได้เมื่อฝึกสม่ำเสมอและไม่ยอมแพ้"}, "storyMai": {"en": "My greatest improvement is confidence, and I can respond more quickly in some situations.", "id": "Kemajuan terbesar saya adalah kepercayaan diri, dan saya bisa merespons lebih cepat dalam beberapa situasi.", "th": "สิ่งที่พัฒนามากที่สุดคือความมั่นใจ และฉันตอบได้เร็วขึ้นในบางสถานการณ์"}, "storyDiep": {"en": "I still make mistakes, but I am no longer so afraid to speak English.", "id": "Saya masih membuat kesalahan, tetapi tidak lagi terlalu takut berbicara bahasa Inggris.", "th": "ฉันยังทำผิดอยู่ แต่ไม่กลัวที่จะพูดภาษาอังกฤษเหมือนเดิม"}, "storyHue": {"en": "The important thing is to start speaking and continue practising.", "id": "Yang penting adalah mulai berbicara dan terus berlatih.", "th": "สิ่งสำคัญคือเริ่มพูดและฝึกต่อไป"}, "translatedQuote": {"en": "Translated learner account · Ho Chi Minh City, Vietnam", "id": "Terjemahan cerita siswa · Ho Chi Minh City, Vietnam", "th": "คำแปลเรื่องราวผู้เรียน · โฮจิมินห์ซิตี เวียดนาม"}, "contactTitle": {"en": "Tell us what you would like to achieve", "id": "Ceritakan tujuan yang ingin Anda capai", "th": "บอกเราว่าคุณอยากทำอะไรได้"}, "formIntro": {"en": "Complete the details first. The course finder is optional. Review your information before sending a free trial request.", "id": "Isi data terlebih dahulu. Panduan kursus bersifat opsional. Tinjau informasi sebelum mengirim permintaan kelas percobaan gratis.", "th": "กรอกข้อมูลก่อน แบบแนะนำหลักสูตรเป็นทางเลือก ตรวจสอบข้อมูลก่อนส่งคำขอบทเรียนทดลองฟรี"}, "name": {"en": "Full name / parent or guardian name", "id": "Nama lengkap / nama orang tua atau wali", "th": "ชื่อ-นามสกุล / ชื่อผู้ปกครอง"}, "phone": {"en": "Phone / WhatsApp number", "id": "Nomor telepon / WhatsApp", "th": "หมายเลขโทรศัพท์ / WhatsApp"}, "email": {"en": "Email (optional)", "id": "Email (opsional)", "th": "อีเมล (ไม่บังคับ)"}, "referred": {"en": "Referred by (optional)", "id": "Direkomendasikan oleh (opsional)", "th": "ผู้แนะนำ (ไม่บังคับ)"}, "level": {"en": "Current English level", "id": "Kemampuan bahasa Inggris saat ini", "th": "ระดับภาษาอังกฤษปัจจุบัน"}, "courseInterest": {"en": "Course of interest (optional)", "id": "Kursus yang diminati (opsional)", "th": "หลักสูตรที่สนใจ (ไม่บังคับ)"}, "track": {"en": "Interview pathway (optional)", "id": "Jalur wawancara (opsional)", "th": "เส้นทางสัมภาษณ์ (ไม่บังคับ)"}, "goal": {"en": "Main learning goal", "id": "Tujuan utama belajar", "th": "เป้าหมายหลักในการเรียน"}, "zone": {"en": "Your local time zone", "id": "Zona waktu Anda", "th": "เขตเวลาของคุณ"}, "time": {"en": "Preferred class time", "id": "Waktu kelas pilihan", "th": "ช่วงเวลาที่สะดวกเรียน"}, "message": {"en": "Message (optional)", "id": "Pesan (opsional)", "th": "ข้อความ (ไม่บังคับ)"}, "optionalAssessment": {"en": "Help me choose a course - optional", "id": "Bantu saya memilih kursus - opsional", "th": "ช่วยฉันเลือกหลักสูตร - ไม่บังคับ"}, "optionalNote": {"en": "You can register without completing this section. Completed assessments, including repeated attempts, are included with your request.", "id": "Anda dapat mendaftar tanpa mengisi bagian ini. Penilaian yang selesai, termasuk pengulangan, disertakan dalam permintaan Anda.", "th": "คุณส่งคำขอได้โดยไม่ทำส่วนนี้ ผลแบบประเมินที่ทำเสร็จรวมถึงการทำซ้ำจะถูกแนบไปกับคำขอ"}, "consent": {"en": "I agree to be contacted about my trial request, classes and scheduling. I have read the privacy notice.", "id": "Saya setuju dihubungi mengenai permintaan percobaan, kelas, dan jadwal. Saya telah membaca pemberitahuan privasi.", "th": "ฉันยินยอมให้ติดต่อเรื่องคำขอทดลองเรียน ชั้นเรียน และตารางเรียน และได้อ่านประกาศความเป็นส่วนตัวแล้ว"}, "review": {"en": "Review details and assessment before sending", "id": "Tinjau data dan penilaian sebelum mengirim", "th": "ตรวจสอบข้อมูลและผลประเมินก่อนส่ง"}, "submit": {"en": "Send trial request", "id": "Kirim permintaan percobaan", "th": "ส่งคำขอทดลองเรียน"}, "emailFallback": {"en": "Send with email app", "id": "Kirim melalui aplikasi email", "th": "ส่งผ่านแอปอีเมล"}, "copy": {"en": "Copy request", "id": "Salin permintaan", "th": "คัดลอกคำขอ"}, "deliveryNote": {"en": "Email is optional; without it we will use your phone/WhatsApp contact. Your request is sent to our support inbox. Email buttons open drafts; press Send in your app.", "id": "Email opsional; tanpa email kami memakai telepon/WhatsApp Anda. Permintaan dikirim ke email dukungan kami. Tombol email membuka draf; tekan Kirim di aplikasi Anda.", "th": "อีเมลไม่บังคับ หากไม่มีจะติดต่อทางโทรศัพท์/WhatsApp คำขอจะส่งไปยังอีเมลทีมดูแลของเรา ปุ่มอีเมลเปิดฉบับร่าง คุณต้องกดส่งในแอป"}, "privacy": {"en": "Privacy", "id": "Privasi", "th": "ความเป็นส่วนตัว"}, "assessmentIntro": {"en": "About four minutes. No contact details needed. This gives a starting suggestion, not a CEFR certificate or speaking-level result.", "id": "Sekitar empat menit. Tidak perlu data kontak. Ini saran awal, bukan sertifikat CEFR atau hasil tingkat kemampuan berbicara.", "th": "ประมาณ 4 นาที ไม่ต้องให้ข้อมูลติดต่อ เป็นเพียงข้อเสนอแนะเริ่มต้น ไม่ใช่ใบรับรอง CEFR หรือผลวัดระดับการพูด"}, "audience": {"en": "Who is the course for?", "id": "Kursus ini untuk siapa?", "th": "หลักสูตรนี้สำหรับใคร"}, "adult": {"en": "Adult learner", "id": "Siswa dewasa", "th": "ผู้เรียนผู้ใหญ่"}, "kids": {"en": "Child aged 4-12; parent completes this", "id": "Anak usia 4-12; diisi orang tua", "th": "เด็กอายุ 4-12 ปี ผู้ปกครองเป็นผู้กรอก"}, "interest": {"en": "Which course interests you most?", "id": "Kursus apa yang paling Anda minati?", "th": "คุณสนใจหลักสูตรใดมากที่สุด"}, "unsure": {"en": "Not sure - help me choose", "id": "Belum yakin - bantu saya memilih", "th": "ยังไม่แน่ใจ ช่วยแนะนำให้ฉัน"}, "task": {"en": "What do you most need to do in English?", "id": "Apa yang paling perlu Anda lakukan dalam bahasa Inggris?", "th": "คุณจำเป็นต้องใช้ภาษาอังกฤษทำอะไรมากที่สุด"}, "urgency": {"en": "When do you need to use English?", "id": "Kapan Anda perlu menggunakan bahasa Inggris?", "th": "คุณต้องใช้ภาษาอังกฤษเมื่อไร"}, "now": {"en": "This month", "id": "Bulan ini", "th": "เดือนนี้"}, "soon": {"en": "Within three months", "id": "Dalam tiga bulan", "th": "ภายใน 3 เดือน"}, "explore": {"en": "No fixed deadline", "id": "Belum ada batas waktu", "th": "ยังไม่มีกำหนด"}, "skill": {"en": "What is hardest for you now?", "id": "Apa yang paling sulit saat ini?", "th": "ตอนนี้ส่วนใดยากที่สุดสำหรับคุณ"}, "skillStart": {"en": "Forming simple sentences", "id": "Membentuk kalimat sederhana", "th": "การสร้างประโยคง่าย ๆ"}, "skillListen": {"en": "Understanding questions", "id": "Memahami pertanyaan", "th": "การเข้าใจคำถาม"}, "skillReply": {"en": "Giving follow-up replies", "id": "Menjawab pertanyaan lanjutan", "th": "การตอบคำถามต่อเนื่อง"}, "skillWords": {"en": "Finding useful words", "id": "Menemukan kata yang tepat", "th": "การนึกคำศัพท์ที่เหมาะสม"}, "experience": {"en": "Have you used English in this situation?", "id": "Pernahkah Anda menggunakan bahasa Inggris dalam situasi ini?", "th": "คุณเคยใช้ภาษาอังกฤษในสถานการณ์นี้หรือไม่"}, "never": {"en": "Not yet", "id": "Belum pernah", "th": "ยังไม่เคย"}, "helped": {"en": "With help", "id": "Dengan bantuan", "th": "โดยมีคนช่วย"}, "independent": {"en": "Independently", "id": "Secara mandiri", "th": "ด้วยตนเอง"}, "practice": {"en": "How much optional practice would suit you?", "id": "Berapa banyak latihan opsional yang cocok untuk Anda?", "th": "คุณสะดวกฝึกเพิ่มเติมตามความสมัครใจเท่าไร"}, "little": {"en": "Very little - focus on class", "id": "Sedikit sekali - fokus di kelas", "th": "น้อยมาก เน้นฝึกในชั้นเรียน"}, "some": {"en": "A little between lessons", "id": "Sedikit di antara kelas", "th": "เล็กน้อยระหว่างบทเรียน"}, "more": {"en": "Regular optional practice", "id": "Latihan opsional rutin", "th": "ฝึกเพิ่มเติมสม่ำเสมอตามความสมัครใจ"}, "sector": {"en": "Preferred work or practice setting", "id": "Lingkungan kerja atau latihan pilihan", "th": "สถานที่ทำงานหรือบริบทที่ต้องการฝึก"}, "confidence": {"en": "How comfortably can you speak English now?", "id": "Seberapa nyaman Anda berbicara bahasa Inggris saat ini?", "th": "ตอนนี้คุณพูดภาษาอังกฤษได้คล่องเพียงใด"}, "confidence0": {"en": "Starting out; need substantial support", "id": "Baru mulai; perlu banyak bantuan", "th": "เพิ่งเริ่ม ต้องการความช่วยเหลือมาก"}, "confidence1": {"en": "Short sentences with pauses", "id": "Kalimat pendek, masih terhenti-henti", "th": "พูดประโยคสั้น ๆ โดยมีหยุดคิด"}, "confidence2": {"en": "Can answer follow-up questions independently", "id": "Bisa menjawab pertanyaan lanjutan secara mandiri", "th": "ตอบคำถามต่อเนื่องได้ด้วยตนเอง"}, "age": {"en": "Child age group", "id": "Kelompok usia anak", "th": "กลุ่มอายุของเด็ก"}, "childGoal": {"en": "Child's main goal", "id": "Tujuan utama anak", "th": "เป้าหมายหลักของเด็ก"}, "childSpeaking": {"en": "Confidence with simple English", "id": "Percaya diri dengan bahasa Inggris sederhana", "th": "มั่นใจในการใช้ภาษาอังกฤษง่าย ๆ"}, "childPlay": {"en": "Songs, stories and playful activities", "id": "Lagu, cerita, dan kegiatan bermain", "th": "เพลง นิทาน และกิจกรรมสนุก ๆ"}, "childSetting": {"en": "Preferred learning arrangement", "id": "Pengaturan belajar pilihan", "th": "รูปแบบการเรียนที่ต้องการ"}, "parent": {"en": "Discuss with parent or guardian", "id": "Diskusikan dengan orang tua atau wali", "th": "พูดคุยกับผู้ปกครอง"}, "smallGroup": {"en": "Small group", "id": "Kelompok kecil", "th": "กลุ่มเล็ก"}, "q1": {"en": "Choose the correct sentence", "id": "Pilih kalimat yang benar", "th": "เลือกประโยคที่ถูกต้อง"}, "q2": {"en": "What does “Could you repeat that, please?” ask for?", "id": "Apa arti permintaan “Could you repeat that, please?”", "th": "“Could you repeat that, please?” เป็นการขออะไร"}, "endCall": {"en": "End a call", "id": "Mengakhiri panggilan", "th": "จบการโทร"}, "confirmUnderstanding": {"en": "Confirm understanding", "id": "Mengonfirmasi pemahaman", "th": "ยืนยันว่าเข้าใจ"}, "repeat": {"en": "Ask someone to say it again", "id": "Meminta seseorang mengulang", "th": "ขอให้พูดอีกครั้ง"}, "q3": {"en": "You are unsure of the deadline. Choose the best reply.", "id": "Anda belum yakin tentang tenggat. Pilih jawaban terbaik.", "th": "คุณยังไม่แน่ใจเรื่องกำหนดส่ง เลือกคำตอบที่เหมาะสมที่สุด"}, "q4": {"en": "Choose the correct question", "id": "Pilih pertanyaan yang benar", "th": "เลือกคำถามที่ถูกต้อง"}, "q5": {"en": "“The meeting has been moved from Tuesday to Thursday.” When is the meeting?", "id": "“The meeting has been moved from Tuesday to Thursday.” Kapan rapat berlangsung?", "th": "“The meeting has been moved from Tuesday to Thursday.” ประชุมวันไหน"}, "bothDays": {"en": "Both days", "id": "Kedua hari", "th": "ทั้งสองวัน"}, "q6": {"en": "You have never used a software tool. Choose an honest reply.", "id": "Anda belum pernah memakai suatu perangkat lunak. Pilih jawaban jujur.", "th": "คุณยังไม่เคยใช้โปรแกรมนี้ เลือกคำตอบที่ตรงกับความจริง"}, "recommend": {"en": "See my recommendation", "id": "Lihat saran saya", "th": "ดูคำแนะนำของฉัน"}, "reset": {"en": "Start again", "id": "Mulai lagi", "th": "เริ่มใหม่"}, "recommendation": {"en": "Your suggested starting point", "id": "Saran titik awal Anda", "th": "จุดเริ่มต้นที่แนะนำ"}, "foundationReason": {"en": "Start with simple sentences and build confidence before progressing to your chosen goal.", "id": "Mulai dengan kalimat sederhana dan bangun percaya diri sebelum melanjutkan ke tujuan Anda.", "th": "เริ่มจากประโยคง่าย ๆ และสร้างความมั่นใจก่อนก้าวไปสู่เป้าหมายที่เลือก"}, "targetReason": {"en": "This suggestion follows your goal, preferred setting and answers. George will confirm suitability through a trial conversation.", "id": "Saran ini mengikuti tujuan, lingkungan pilihan, dan jawaban Anda. George mengonfirmasi kesesuaian melalui percakapan percobaan.", "th": "คำแนะนำนี้อิงจากเป้าหมาย บริบทที่เลือก และคำตอบของคุณ George จะยืนยันความเหมาะสมผ่านการสนทนาทดลอง"}, "kidsReason": {"en": "A parent or guardian selected Kids. George will discuss age, activities and suitable support.", "id": "Orang tua atau wali memilih Kids. George akan membahas usia, kegiatan, dan dukungan yang sesuai.", "th": "ผู้ปกครองเลือก Kids George จะพูดคุยเรื่องอายุ กิจกรรม และการดูแลที่เหมาะสม"}, "limit": {"en": "The short written check does not measure pronunciation, live listening or CEFR level. Recommendations do not enrol you or require payment.", "id": "Tes tulis singkat tidak mengukur pelafalan, menyimak langsung, atau tingkat CEFR. Saran tidak mendaftarkan Anda atau mewajibkan pembayaran.", "th": "คำถามเขียนสั้น ๆ ไม่ได้วัดการออกเสียง การฟังสด หรือระดับ CEFR คำแนะนำไม่ได้สมัครเรียนให้คุณหรือบังคับชำระเงิน"}, "next": {"en": "Follow-on goal", "id": "Tujuan berikutnya", "th": "เป้าหมายถัดไป"}, "shortCheck": {"en": "Short English check", "id": "Tes singkat bahasa Inggris", "th": "คำถามภาษาอังกฤษสั้น ๆ"}, "attempts": {"en": "Completed assessment attempts included", "id": "Percobaan penilaian selesai yang disertakan", "th": "จำนวนแบบประเมินที่เสร็จและแนบแล้ว"}, "noAssessment": {"en": "No self-assessment completed; discuss in the trial.", "id": "Belum mengisi penilaian; diskusikan saat percobaan.", "th": "ยังไม่ได้ทำแบบประเมิน พูดคุยในบทเรียนทดลองได้"}, "incomplete": {"en": "Complete the remaining questions to see a recommendation, or skip this optional section and register.", "id": "Lengkapi pertanyaan untuk melihat saran, atau lewati bagian opsional ini dan daftar.", "th": "ตอบคำถามที่เหลือเพื่อดูคำแนะนำ หรือข้ามส่วนนี้และส่งคำขอได้"}, "copied": {"en": "Request copied. Paste it into your email or WhatsApp message.", "id": "Permintaan disalin. Tempel ke email atau pesan WhatsApp.", "th": "คัดลอกคำขอแล้ว วางในอีเมลหรือข้อความ WhatsApp ได้"}, "copyError": {"en": "Automatic copying was unavailable. Select and copy the preview text instead.", "id": "Penyalinan otomatis tidak tersedia. Pilih dan salin teks pratinjau.", "th": "คัดลอกอัตโนมัติไม่ได้ กรุณาเลือกและคัดลอกข้อความตัวอย่าง"}, "draftOpened": {"en": "Email draft opened. Review it and press Send in your email app.", "id": "Draf email dibuka. Tinjau dan tekan Kirim di aplikasi email.", "th": "เปิดร่างอีเมลแล้ว ตรวจสอบและกดส่งในแอปอีเมล"}, "success": {"en": "Thank you. Your request was submitted for processing. This is not a confirmed class time or paid enrolment.", "id": "Terima kasih. Permintaan dikirim untuk diproses. Ini bukan konfirmasi jadwal kelas atau pendaftaran berbayar.", "th": "ขอบคุณ ส่งคำขอเพื่อดำเนินการแล้ว ยังไม่ใช่การยืนยันเวลาเรียนหรือการสมัครแบบชำระเงิน"}, "sending": {"en": "Opening the secure submission service…", "id": "Membuka layanan pengiriman aman…", "th": "กำลังเปิดบริการส่งแบบฟอร์ม…"}, "select": {"en": "Choose an answer", "id": "Pilih jawaban", "th": "เลือกคำตอบ"}, "beginnerLevel": {"en": "Starting / Beginner", "id": "Baru mulai / Beginner", "th": "เพิ่งเริ่ม / Beginner"}, "basicLevel": {"en": "Basic sentences", "id": "Kalimat dasar", "th": "ประโยคพื้นฐาน"}, "conversationLevel": {"en": "Can hold a conversation", "id": "Bisa bercakap-cakap", "th": "สนทนาได้"}, "everyday": {"en": "Everyday conversation", "id": "Percakapan sehari-hari", "th": "สนทนาในชีวิตประจำวัน"}, "work": {"en": "Work, meetings and emails", "id": "Pekerjaan, rapat, dan email", "th": "การทำงาน การประชุม และอีเมล"}, "interviewTask": {"en": "Job applications and interviews", "id": "Lamaran dan wawancara kerja", "th": "การสมัครงานและสัมภาษณ์"}, "service": {"en": "Talking with customers", "id": "Berbicara dengan pelanggan", "th": "พูดคุยกับลูกค้า"}, "relationship": {"en": "Cross-cultural relationships (18+)", "id": "Hubungan lintas budaya (18+)", "th": "ความสัมพันธ์ข้ามวัฒนธรรม (18+)"}, "corporate": {"en": "A corporate team programme", "id": "Program tim perusahaan", "th": "หลักสูตรสำหรับทีมองค์กร"}, "travel": {"en": "Travel and everyday situations", "id": "Perjalanan dan situasi sehari-hari", "th": "การเดินทางและสถานการณ์ทั่วไป"}, "flexible": {"en": "Flexible - discuss a suitable time", "id": "Fleksibel - diskusikan waktu yang sesuai", "th": "ยืดหยุ่น พูดคุยเวลาที่เหมาะสม"}, "faq1": {"en": "Can a beginner join?", "id": "Apakah pemula bisa ikut?", "th": "ผู้เริ่มต้นเรียนได้ไหม"}, "faq1a": {"en": "Yes. We begin with useful words, simple sentences and patient speaking practice. No perfect grammar is needed.", "id": "Ya. Kita mulai dengan kata berguna, kalimat sederhana, dan latihan berbicara yang sabar. Tidak perlu tata bahasa sempurna.", "th": "ได้ เราเริ่มด้วยคำศัพท์ที่ใช้ได้ ประโยคง่าย ๆ และการฝึกพูดอย่างใจเย็น ไม่ต้องใช้ไวยากรณ์ได้สมบูรณ์แบบ"}, "faq2": {"en": "How do online lessons work?", "id": "Bagaimana kelas online berlangsung?", "th": "บทเรียนออนไลน์เป็นอย่างไร"}, "faq2a": {"en": "Live lessons use Microsoft Teams. You need internet, a microphone, headphones or speakers and a quiet place. Confirm the date, time zone and meeting link before class.", "id": "Kelas langsung memakai Microsoft Teams. Anda perlu internet, mikrofon, headphone atau speaker, dan tempat tenang. Konfirmasi tanggal, zona waktu, dan tautan sebelum kelas.", "th": "เรียนสดผ่าน Microsoft Teams ต้องมีอินเทอร์เน็ต ไมโครโฟน หูฟังหรือลำโพง และที่เงียบ ยืนยันวันที่ เขตเวลา และลิงก์ก่อนเรียน"}, "faq3": {"en": "Do I have to take the assessment?", "id": "Apakah penilaian wajib?", "th": "ต้องทำแบบประเมินไหม"}, "faq3a": {"en": "No. You can request a trial without it. Completed answers help us prepare and are sent only when you submit or share your request.", "id": "Tidak. Anda dapat meminta percobaan tanpa penilaian. Jawaban yang selesai membantu persiapan dan dikirim hanya saat Anda mengirim atau membagikan permintaan.", "th": "ไม่จำเป็น คุณขอทดลองเรียนได้โดยไม่ทำ ผลที่ทำเสร็จช่วยให้เราเตรียมตัว และจะถูกส่งเมื่อคุณส่งหรือแชร์คำขอเท่านั้น"}, "faq4": {"en": "Are these academic or professional qualifications?", "id": "Apakah ini kualifikasi akademik atau profesi?", "th": "หลักสูตรนี้เป็นวุฒิการศึกษาหรือใบรับรองวิชาชีพไหม"}, "faq4a": {"en": "No. These are basic, practical English courses. They do not certify job competence or replace occupational training.", "id": "Bukan. Ini kursus bahasa Inggris dasar dan praktis. Tidak menyertifikasi kompetensi kerja atau menggantikan pelatihan profesi.", "th": "ไม่ใช่ เป็นหลักสูตรภาษาอังกฤษพื้นฐานที่ใช้ได้จริง ไม่รับรองความสามารถทางวิชาชีพหรือแทนการฝึกอาชีพ"}, "faq5": {"en": "How do I receive a student account?", "id": "Bagaimana mendapat akun siswa?", "th": "จะได้รับบัญชีผู้เรียนอย่างไร"}, "faq5a": {"en": "An account is arranged privately after enrolment is confirmed. A trial enquiry does not create an account. Use your own login and never share passwords.", "id": "Akun diatur secara pribadi setelah pendaftaran dikonfirmasi. Pertanyaan percobaan tidak membuat akun. Gunakan akun sendiri dan jangan bagikan kata sandi.", "th": "จะจัดบัญชีให้เป็นการส่วนตัวหลังยืนยันการสมัคร การสอบถามทดลองเรียนไม่สร้างบัญชี ใช้บัญชีของตนและไม่แชร์รหัสผ่าน"}, "faq6": {"en": "What if I need to reschedule or request a refund?", "id": "Bagaimana jika perlu mengubah jadwal atau meminta pengembalian dana?", "th": "หากต้องการเปลี่ยนเวลาหรือขอคืนเงินต้องทำอย่างไร"}, "faq6a": {"en": "Contact support as early as possible. Availability and the written terms agreed before payment apply. No replacement date is confirmed until agreed in writing.", "id": "Hubungi dukungan sedini mungkin. Berlaku ketersediaan dan ketentuan tertulis sebelum pembayaran. Tanggal pengganti belum pasti sampai disepakati tertulis.", "th": "ติดต่อทีมดูแลโดยเร็วที่สุด ขึ้นอยู่กับที่ว่างและเงื่อนไขที่ตกลงเป็นลายลักษณ์อักษรก่อนชำระ วันทดแทนยังไม่ยืนยันจนกว่าจะตกลงเป็นลายลักษณ์อักษร"}, "faq7": {"en": "Is homework compulsory?", "id": "Apakah tugas wajib?", "th": "บังคับทำการบ้านไหม"}, "faq7a": {"en": "No. Practice outside class is optional. Ask for support that fits your time and confidence.", "id": "Tidak. Latihan di luar kelas opsional. Mintalah dukungan yang sesuai waktu dan kepercayaan diri Anda.", "th": "ไม่บังคับ การฝึกนอกชั้นเรียนเป็นทางเลือก ขอคำแนะนำให้เหมาะกับเวลาและความมั่นใจของคุณได้"}, "faq8": {"en": "Who can use Kids and Love Across Borders?", "id": "Siapa yang bisa mengikuti Kids dan Love Across Borders?", "th": "ใครเรียน Kids และ Love Across Borders ได้บ้าง"}, "faq8a": {"en": "Kids is for ages 4-12 with a parent or guardian handling registration. Love Across Borders is only for adults 18+, with respectful communication and safety in focus.", "id": "Kids untuk usia 4-12 dengan pendaftaran oleh orang tua atau wali. Love Across Borders hanya untuk dewasa 18+, berfokus pada komunikasi saling menghormati dan keselamatan.", "th": "Kids สำหรับอายุ 4-12 ปี โดยผู้ปกครองจัดการสมัคร Love Across Borders สำหรับผู้ใหญ่ 18 ปีขึ้นไป เน้นการสื่อสารที่ให้เกียรติและความปลอดภัย"}, "faq9": {"en": "How are my details used?", "id": "Bagaimana data saya digunakan?", "th": "ใช้ข้อมูลของฉันอย่างไร"}, "faq9a": {"en": "We use enquiry details to contact you about your request, courses and schedules. We do not sell your personal information. See the privacy page for providers and contact options.", "id": "Kami memakai data pertanyaan untuk menghubungi Anda tentang permintaan, kursus, dan jadwal. Kami tidak menjual data pribadi Anda. Lihat halaman privasi untuk penyedia layanan dan kontak.", "th": "เราใช้ข้อมูลคำขอเพื่อติดต่อเรื่องคำขอ หลักสูตร และตารางเรียน เราไม่ขายข้อมูลส่วนบุคคล อ่านหน้าความเป็นส่วนตัวเพื่อดูผู้ให้บริการและวิธีติดต่อ"}, "faq10": {"en": "I forgot my password. What should I do?", "id": "Saya lupa kata sandi. Apa yang harus dilakukan?", "th": "ลืมรหัสผ่านควรทำอย่างไร"}, "faq10a": {"en": "Contact support through your usual registered contact. Identity must be checked before access is reset. Never send your old password.", "id": "Hubungi dukungan melalui kontak terdaftar Anda. Identitas harus diperiksa sebelum akses diatur ulang. Jangan kirim kata sandi lama.", "th": "ติดต่อผ่านช่องทางที่ใช้ลงทะเบียน ต้องตรวจสอบตัวตนก่อนรีเซ็ตสิทธิ์เข้าใช้งาน ห้ามส่งรหัสผ่านเดิม"}, "faq11": {"en": "Can the advisor change my booking automatically?", "id": "Bisakah penasihat mengubah pemesanan otomatis?", "th": "ที่ปรึกษาเปลี่ยนการจองให้อัตโนมัติได้ไหม"}, "faq11a": {"en": "The virtual advisor provides prepared guidance. Booking, account and payment requests require a response from the Talk English team.", "id": "Penasihat virtual menyediakan panduan yang telah disiapkan. Permintaan pemesanan, akun, dan pembayaran memerlukan jawaban tim Talk English.", "th": "ที่ปรึกษาเสมือนให้คำแนะนำที่เตรียมไว้ คำขอเกี่ยวกับการจอง บัญชี และการชำระเงินต้องรอคำตอบจากทีม Talk English"}, "privacy1": {"en": "Course finder answers stay in page memory until you submit or share a request. Reloading or closing the page clears them. Only your language preference is saved on this browser.", "id": "Jawaban panduan kursus tetap dalam memori halaman sampai Anda mengirim atau membagikan permintaan. Memuat ulang atau menutup halaman menghapusnya. Hanya pilihan bahasa yang disimpan di peramban ini.", "th": "คำตอบแบบแนะนำหลักสูตรอยู่ในหน่วยความจำของหน้าเว็บจนกว่าคุณจะส่งหรือแชร์คำขอ การรีโหลดหรือปิดหน้าจะล้างคำตอบ มีเพียงภาษาที่เลือกเท่านั้นที่บันทึกในเบราว์เซอร์"}, "privacy2": {"en": "When you submit a form, your contact details, message, consent and completed assessment attempts are sent through FormSubmit to our branded inbox. FormSubmit and the email provider process that data under their own policies. Email is optional; an acknowledgement depends on service activation and delivery.", "id": "Saat mengirim formulir, data kontak, pesan, persetujuan, dan penilaian yang selesai dikirim melalui FormSubmit ke email resmi kami. FormSubmit dan penyedia email memproses data sesuai kebijakannya. Email opsional; tanda terima bergantung pada aktivasi dan pengiriman layanan.", "th": "เมื่อส่งแบบฟอร์ม ข้อมูลติดต่อ ข้อความ ความยินยอม และผลประเมินที่เสร็จจะส่งผ่าน FormSubmit ไปยังอีเมลของเรา FormSubmit และผู้ให้บริการอีเมลประมวลผลตามนโยบายของตน อีเมลไม่บังคับ การตอบรับขึ้นอยู่กับการเปิดใช้และการส่งถึง"}, "privacy3": {"en": "An email link opens your email app. A WhatsApp link opens a prepared message. Review it and press Send yourself; WhatsApp then receives your message and account information under its policies.", "id": "Tautan email membuka aplikasi email. Tautan WhatsApp membuka pesan siap kirim. Tinjau dan tekan Kirim sendiri; WhatsApp kemudian menerima pesan dan informasi akun sesuai kebijakannya.", "th": "ลิงก์อีเมลเปิดแอปอีเมล ลิงก์ WhatsApp เปิดข้อความที่เตรียมไว้ ตรวจสอบและกดส่งด้วยตนเอง จากนั้น WhatsApp จะรับข้อความและข้อมูลบัญชีตามนโยบายของบริการ"}, "privacy4": {"en": "Private student accounts and learning records use Supabase. The virtual advisor portrait is an illustrative character, not a staff photograph. Contact us to ask about your information or request deletion. Do not send passwords, identity documents, health information or payment-card details.", "id": "Akun siswa dan catatan belajar pribadi memakai Supabase. Potret penasihat virtual adalah ilustrasi karakter, bukan foto staf. Hubungi kami untuk menanyakan data atau meminta penghapusan. Jangan kirim kata sandi, dokumen identitas, informasi kesehatan, atau data kartu pembayaran.", "th": "บัญชีผู้เรียนและข้อมูลการเรียนส่วนตัวใช้ Supabase ภาพที่ปรึกษาเสมือนเป็นภาพตัวละคร ไม่ใช่รูปพนักงาน ติดต่อเพื่อสอบถามข้อมูลของคุณหรือขอลบข้อมูล อย่าส่งรหัสผ่าน เอกสารยืนยันตัวตน ข้อมูลสุขภาพ หรือข้อมูลบัตรชำระเงิน"}, "skip": {"en": "Skip to main content", "id": "Langsung ke konten utama", "th": "ข้ามไปเนื้อหาหลัก"}, "menu": {"en": "Menu", "id": "Menu", "th": "เมนู"}, "registerWithResult": {"en": "Request a trial with this recommendation", "id": "Minta percobaan dengan saran ini", "th": "ขอทดลองเรียนพร้อมคำแนะนำนี้"}, "studentText": {"en": "Your personal lessons, optional practice and feedback. Use the account supplied after confirmed enrolment.", "id": "Pelajaran pribadi, latihan opsional, dan umpan balik Anda. Gunakan akun yang diberikan setelah pendaftaran dikonfirmasi.", "th": "บทเรียนส่วนตัว การฝึกตามความสมัครใจ และคำแนะนำ ใช้บัญชีที่ได้รับหลังยืนยันการสมัคร"}, "selectGoal": {"en": "Choose your goal and starting point", "id": "Pilih tujuan dan titik awal", "th": "เลือกเป้าหมายและจุดเริ่มต้น"}, "safeContact": {"en": "Do not send passwords or payment details. Enquiries do not confirm a booking.", "id": "Jangan kirim kata sandi atau data pembayaran. Pertanyaan tidak mengonfirmasi pemesanan.", "th": "อย่าส่งรหัสผ่านหรือข้อมูลการชำระเงิน การสอบถามยังไม่ยืนยันการจอง"}, "course_beginner": {"en": "Beginner English", "id": "Bahasa Inggris Pemula", "th": "ภาษาอังกฤษสำหรับผู้เริ่มต้น"}, "desc_beginner": {"en": "Introductions, simple questions and useful everyday sentences.", "id": "Perkenalan, pertanyaan sederhana, dan kalimat sehari-hari.", "th": "แนะนำตัว คำถามง่าย ๆ และประโยคที่ใช้ในชีวิตประจำวัน"}, "course_daily": {"en": "Daily Conversation", "id": "Percakapan Sehari-hari", "th": "บทสนทนาในชีวิตประจำวัน"}, "desc_daily": {"en": "Build short conversations about familiar situations.", "id": "Bangun percakapan singkat tentang situasi yang akrab.", "th": "ฝึกสนทนาสั้น ๆ ในสถานการณ์คุ้นเคย"}, "course_business": {"en": "Business English Essentials", "id": "Dasar Bahasa Inggris Bisnis", "th": "ภาษาอังกฤษธุรกิจพื้นฐาน"}, "desc_business": {"en": "Work updates, meetings, requests and emails.", "id": "Informasi kerja, rapat, permintaan, dan email.", "th": "แจ้งความคืบหน้างาน ประชุม ขอความช่วยเหลือ และอีเมล"}, "course_interview": {"en": "Job Search & Interview English", "id": "Bahasa Inggris Lamaran & Wawancara", "th": "ภาษาอังกฤษสมัครงานและสัมภาษณ์"}, "desc_interview": {"en": "Describe your experience, prepare applications and practise honest interview answers.", "id": "Ceritakan pengalaman, siapkan lamaran, dan latih jawaban wawancara yang jujur.", "th": "เล่าประสบการณ์ เตรียมสมัครงาน และฝึกคำตอบสัมภาษณ์ตามจริง"}, "course_cruise": {"en": "Cruise Ship English", "id": "Bahasa Inggris Kapal Pesiar", "th": "ภาษาอังกฤษเรือสำราญ"}, "desc_cruise": {"en": "Communicate with guests and colleagues on cruise ships.", "id": "Berkomunikasi dengan tamu dan rekan di kapal pesiar.", "th": "สื่อสารกับแขกและเพื่อนร่วมงานบนเรือสำราญ"}, "course_hotel": {"en": "Hotel & Resort English", "id": "Bahasa Inggris Hotel & Resor", "th": "ภาษาอังกฤษโรงแรมและรีสอร์ต"}, "desc_hotel": {"en": "Practise familiar guest-service conversations.", "id": "Latih percakapan layanan tamu yang umum.", "th": "ฝึกบทสนทนาบริการแขกที่พบบ่อย"}, "course_office-it": {"en": "International Office & IT English", "id": "Bahasa Inggris Kantor Internasional & TI", "th": "ภาษาอังกฤษสำนักงานนานาชาติและไอที"}, "desc_office-it": {"en": "Clear everyday communication in offices and IT support.", "id": "Komunikasi sehari-hari yang jelas di kantor dan dukungan TI.", "th": "สื่อสารในสำนักงานและงานสนับสนุนไอทีให้ชัดเจน"}, "course_manufacturing-construction": {"en": "Manufacturing & Construction English", "id": "Bahasa Inggris Manufaktur & Konstruksi", "th": "ภาษาอังกฤษการผลิตและก่อสร้าง"}, "desc_manufacturing-construction": {"en": "Talk about simple workplace tasks and ask for clarification.", "id": "Bicarakan tugas kerja sederhana dan minta penjelasan.", "th": "พูดเรื่องงานพื้นฐานและขอคำอธิบายเพิ่มเติม"}, "course_maritime": {"en": "Maritime & Seafarer English", "id": "Bahasa Inggris Maritim & Pelaut", "th": "ภาษาอังกฤษทางทะเลและคนประจำเรือ"}, "desc_maritime": {"en": "Everyday communication with multinational crews.", "id": "Komunikasi sehari-hari dengan kru multinasional.", "th": "สื่อสารในชีวิตประจำวันกับลูกเรือหลายชาติ"}, "course_massage-spa": {"en": "Massage & Spa English", "id": "Bahasa Inggris Pijat & Spa", "th": "ภาษาอังกฤษนวดและสปา"}, "desc_massage-spa": {"en": "Explain services and respond respectfully to clients.", "id": "Jelaskan layanan dan tanggapi klien dengan hormat.", "th": "อธิบายบริการและตอบลูกค้าอย่างให้เกียรติ"}, "course_nail": {"en": "Nail Salon English", "id": "Bahasa Inggris Salon Kuku", "th": "ภาษาอังกฤษร้านทำเล็บ"}, "desc_nail": {"en": "Discuss appointments, preferences and simple services.", "id": "Bicarakan janji, preferensi, dan layanan sederhana.", "th": "พูดคุยเรื่องนัดหมาย ความต้องการ และบริการพื้นฐาน"}, "course_restaurant-service": {"en": "Restaurant & Customer Service English", "id": "Bahasa Inggris Restoran & Layanan Pelanggan", "th": "ภาษาอังกฤษร้านอาหารและบริการลูกค้า"}, "desc_restaurant-service": {"en": "Take requests and respond to common customer questions.", "id": "Terima permintaan dan jawab pertanyaan pelanggan umum.", "th": "รับคำขอและตอบคำถามลูกค้าที่พบบ่อย"}, "course_warehousing-logistics": {"en": "Warehousing & Logistics English", "id": "Bahasa Inggris Gudang & Logistik", "th": "ภาษาอังกฤษคลังสินค้าและโลจิสติกส์"}, "desc_warehousing-logistics": {"en": "Talk about stock, deliveries and practical work updates.", "id": "Bicarakan stok, pengiriman, dan informasi pekerjaan praktis.", "th": "พูดเรื่องสต็อก การส่งสินค้า และความคืบหน้างาน"}, "course_love-across-borders": {"en": "Love Across Borders", "id": "Love Across Borders", "th": "Love Across Borders"}, "desc_love-across-borders": {"en": "Respectful cross-cultural relationship communication, boundaries and safety. Adults 18+.", "id": "Komunikasi hubungan lintas budaya, batasan, dan keselamatan. Dewasa 18+.", "th": "สื่อสารความสัมพันธ์ข้ามวัฒนธรรม ขอบเขต และความปลอดภัย ผู้ใหญ่ 18+"}, "course_corporate-a1": {"en": "Corporate English A1", "id": "Bahasa Inggris Perusahaan A1", "th": "ภาษาอังกฤษองค์กร A1"}, "desc_corporate-a1": {"en": "Basic practical communication for company teams.", "id": "Komunikasi praktis dasar untuk tim perusahaan.", "th": "การสื่อสารพื้นฐานใช้งานจริงสำหรับทีมองค์กร"}, "course_corporate-a2": {"en": "Corporate English A2", "id": "Bahasa Inggris Perusahaan A2", "th": "ภาษาอังกฤษองค์กร A2"}, "desc_corporate-a2": {"en": "More independent workplace communication for company teams.", "id": "Komunikasi kerja lebih mandiri untuk tim perusahaan.", "th": "สื่อสารในที่ทำงานอย่างเป็นอิสระขึ้นสำหรับทีมองค์กร"}, "course_kids": {"en": "Talk English Kids", "id": "Talk English Kids", "th": "Talk English Kids"}, "desc_kids": {"en": "Songs, stories and practical language through age-appropriate activities.", "id": "Lagu, cerita, dan bahasa praktis melalui kegiatan sesuai usia.", "th": "เพลง นิทาน และภาษาใช้งานจริงผ่านกิจกรรมเหมาะกับวัย"}, "q1a": {"en": "She work here.", "id": "She work here.", "th": "She work here."}, "q1b": {"en": "She works here.", "id": "She works here.", "th": "She works here."}, "q1c": {"en": "She working here.", "id": "She working here.", "th": "She working here."}, "q3a": {"en": "Could you confirm the deadline, please?", "id": "Could you confirm the deadline, please?", "th": "Could you confirm the deadline, please?"}, "q3b": {"en": "I guarantee it is finished.", "id": "I guarantee it is finished.", "th": "I guarantee it is finished."}, "q3c": {"en": "I will guess the time.", "id": "I will guess the time.", "th": "I will guess the time."}, "q4a": {"en": "Where you work?", "id": "Where you work?", "th": "Where you work?"}, "q4b": {"en": "Where do you work?", "id": "Where do you work?", "th": "Where do you work?"}, "q4c": {"en": "Where does you work?", "id": "Where does you work?", "th": "Where does you work?"}, "tuesday": {"en": "Tuesday", "id": "Tuesday", "th": "Tuesday"}, "thursday": {"en": "Thursday", "id": "Thursday", "th": "Thursday"}, "q6a": {"en": "I am an expert in it.", "id": "I am an expert in it.", "th": "I am an expert in it."}, "q6b": {"en": "I have used it for years.", "id": "I have used it for years.", "th": "I have used it for years."}, "q6c": {"en": "I have not used it yet, but I am willing to learn.", "id": "I have not used it yet, but I am willing to learn.", "th": "I have not used it yet, but I am willing to learn."}, "advanced": {"en": "Advanced", "id": "Advanced", "th": "Advanced"}, "age46": {"en": "4-6", "id": "4-6", "th": "4-6"}, "age79": {"en": "7-9", "id": "7-9", "th": "7-9"}, "age1012": {"en": "10-12", "id": "10-12", "th": "10-12"}, "zoneWib": {"en": "WIB - Jakarta (UTC+7)", "id": "WIB - Jakarta (UTC+7)", "th": "WIB - Jakarta (UTC+7)"}, "zoneWita": {"en": "WITA - Bali / Makassar (UTC+8)", "id": "WITA - Bali / Makassar (UTC+8)", "th": "WITA - Bali / Makassar (UTC+8)"}, "zoneWit": {"en": "WIT - Papua (UTC+9)", "id": "WIT - Papua (UTC+9)", "th": "WIT - Papua (UTC+9)"}, "zoneBangkok": {"en": "ICT - Bangkok (UTC+7)", "id": "ICT - Bangkok (UTC+7)", "th": "ICT - Bangkok (UTC+7)"}, "fxNote": {"en": "Thai prices use the midpoint of Bank Indonesia’s published THB buy/sell rates on 23 October 2026: 535.92 IDR per THB. Converted amounts are rounded to ฿300 / ฿1,050. Prices are fixed until updated; they are not live exchange quotes.", "id": "Harga Thailand memakai titik tengah kurs beli/jual THB Bank Indonesia 23 Oktober 2026: 535,92 IDR per THB. Harga dibulatkan menjadi ฿300 / ฿1.050. Harga tetap sampai diperbarui, bukan kurs langsung.", "th": "ราคาไทยใช้อัตรากลางระหว่างราคาซื้อ/ขาย THB ของ Bank Indonesia วันที่ 23 ตุลาคม 2026 ที่ 535.92 IDR ต่อ THB ปัดเป็น ฿300 / ฿1,050 ราคาคงที่จนกว่าจะปรับ ไม่ใช่อัตราแลกเปลี่ยนแบบสด"}};
